function save(){try{localStorage.setItem('pv-workspace-v1',JSON.stringify({cfg,opcfg,levels,tasks,cleared,logs:logs.slice(-100)}));}catch{toast('浏览器未允许本地保存，本次会话仍可使用');}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function log(text){logs.push(`${new Date().toLocaleTimeString('zh-CN',{hour12:false})} ${text}`);logs=logs.slice(-100);save();}
function compute(){if(cache)return cache;const input=scenario(cfg),rolling=dispatch(input,cfg,'rolling'),rule=dispatch(input,cfg,'rule'),none=dispatch(input,cfg,'none');return cache={input,rolling,rule,none};}
function rowsForEvaluation(){let r=b.test.filter(x=>x.day);if(forecastDay!=='all')r=r.filter(x=>x.time.startsWith(forecastDay));return r;}
function selectedMetrics(){const r=rowsForEvaluation();return {r,m:metrics(r.map(x=>x.actual),r.map(x=>x[forecastModel]),b.capacity),baseline:metrics(r.map(x=>x.actual),r.map(x=>x.persist),b.capacity)};}
function loss(i){return cleared.includes(i)?1:clamp(cfg.dust*(.4+1.45*((i*17%47)/47)),.5,45);}
function arrayMap(interactive=true){return `<div class="map-meta"><span>北 ↑ · 6行 × 8列分区</span><span>局部示意 · 非地理坐标</span></div><div class="array-map">${Array.from({length:48},(_,i)=>`<button class="pv-cell ${loss(i)>10?'high':loss(i)>6?'medium':''} ${selected.has(i)?'selected':''}" data-cell="${i}" title="分区A${String(i+1).padStart(2,'0')}，假设污染损失${num(loss(i))}%，点击${interactive?'选择':'查看'}" aria-pressed="${selected.has(i)}">A${String(i+1).padStart(2,'0')}<b>${num(loss(i),0)}%</b></button>`).join('')}</div><div class="map-key"><span><i></i>≤6%</span><span><i class="mid"></i>6–10%</span><span><i class="high"></i>>10%</span><span>金边：已选区域</span></div>`;}
function sceneSVG(){let panels='';for(let r=0;r<5;r++)for(let c=0;c<7;c++){let x=70+c*43+r*16,y=82+r*29-c*8;panels+=`<path d="M${x} ${y}l32-6 13 17-32 7z" fill="${(r+c)%6===0?'#a88e5d':'#476475'}" stroke="#6d8792" stroke-width=".7"/><path d="M${x+11} ${y-2}l13 17M${x+22} ${y-4}l13 17M${x+6} ${y+8}l31-6" stroke="#adc4c8" opacity=".3" stroke-width=".5"/>`;}
 return `<svg class="hero-scene" viewBox="0 0 510 290" aria-label="光伏阵列、储能与无人机协同示意" role="img"><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" stroke="#75827a" stroke-width=".4" fill="none" opacity=".22"/></pattern></defs><rect width="510" height="290" fill="url(#grid)"/><path d="M30 185 320 37 494 151 193 282z" fill="#39433e" stroke="#657161" stroke-width=".5"/>${panels}<path d="M107 225 197 256 460 153" fill="none" stroke="#b99862" stroke-dasharray="4 5" opacity=".8"/><g transform="translate(383,146)"><path d="M0 0l31-7v58l-31 8z" fill="#d9ded2"/><path d="M31-7l20 11v58l-20-11z" fill="#8e9b94"/><path d="M6 10l18-4v12L6 22z" fill="#557568"/><path d="M14 27l-4 9h8l-3 10" fill="none" stroke="#a68b58" stroke-width="2"/></g><g transform="translate(310,40)" stroke="#d9c18d" stroke-width="1.6" fill="none"><path d="M-12-5h24v13h-24zM-12-5l-14-8M12-5l14-8M-12 8l-14 8M12 8l14 8"/><ellipse cx="-27" cy="-14" rx="11" ry="3"/><ellipse cx="27" cy="-14" rx="11" ry="3"/><ellipse cx="-27" cy="17" rx="11" ry="3"/><ellipse cx="27" cy="17" rx="11" ry="3"/></g><path d="M310 58 180 196M310 58l65 77" stroke="#dcc893" stroke-dasharray="3 5" stroke-width=".8" opacity=".5"/><text x="346" y="32" font-size="9" fill="#cfb787" font-family="monospace">UAV · INSPECTION</text><text x="390" y="228" font-size="9" fill="#aebbb6" font-family="monospace">ESS · 200 kWh</text><text x="58" y="261" font-size="9" fill="#afbbb6" font-family="monospace">PV ARRAY / LOCAL SCHEMATIC</text></svg>`;
}
function shell(){const n=navs.find(n=>n[0]===page)||navs[0];$('#app').innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><svg class="brand-mark" viewBox="0 0 40 44" aria-hidden="true"><path d="M20 1 37 11v20L20 42 3 31V11z" fill="#ac2935"/><path d="m10 27 10-17 10 17M14 21h12M10 31h20" fill="none" stroke="#f4d494" stroke-width="2"/></svg><div><strong>ChinaOil <span class="red">Solar</span></strong><small>INTELLIGENT ENERGY</small></div></div><div class="site-selector"><b>新疆油田 · 百口泉场景</b><span>光伏 / 储能 / 智能运维</span></div><div class="section-label">协同研究工作空间</div><nav class="nav" aria-label="主导航">${navs.map((n,i)=>`<button data-page="${n[0]}" class="${page===n[0]?'active':''}" aria-current="${page===n[0]?'page':'false'}">${icon(n[2])}${n[1]}<span class="num">0${i+1}</span></button>`).join('')}</nav><div class="side-foot"><span class="dot amber"></span>研究与试点工作空间<strong>公开回放 + 情景推演</strong><div class="mini-bars">${[8,12,10,18,16,22,17,13,19,12,8].map(h=>`<i style="height:${h}px"></i>`).join('')}</div><div>设备接入：未连接 / 演练</div><a href="https://github.com/oilreservior123/photovoltaic-power" target="_blank" rel="noopener">项目仓库 ↗</a></div></aside><header class="topbar"><div class="row"><button class="btn small menu-toggle" data-action="menu" aria-label="展开导航">${icon('menu')}</button><div class="crumb">光伏协同系统 <span style="margin:0 9px;color:#ccc">/</span> <b>${n[1]}</b></div></div><div class="top-actions"><span class="desktop"><span class="dot"></span>计算内核就绪</span><span class="hide-mobile muted">公开样本：2020.05–06</span><button class="btn small" data-action="export-report">${icon('download')} 导出报告</button><div class="avatar">BQ</div></div></header><main class="main" id="main-content"></main></div>`;renderPage();}
function heading(en,title,desc,actions=''){return `<header class="head"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="row">${actions}</div>`:''}</header>`;}
function footer(){return `<footer class="footer"><span>光伏发电效率实时预测与智能调配系统 · 百口泉采油厂应用场景</span><span>研究演示 V1.0 / 现场数据与设备待接入</span></footer>`;}
function overview(){const x=compute(),s=replay.stats,m=metrics(b.test.filter(r=>r.day).map(r=>r.actual),b.test.filter(r=>r.day).map(r=>r.pred)),mp=metrics(b.test.filter(r=>r.day).map(r=>r.actual),b.test.filter(r=>r.day).map(r=>r.persist));return heading('PHOTOVOLTAIC INTELLIGENCE','光伏发电效率实时预测与智能调配系统','从可用出力预测，到储能决策，再到污染定位与清扫复核。',`<span class="tag">百口泉应用场景</span><button class="btn primary" data-page="dispatch">进入调配工作台 ${icon('arrow')}</button>`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">PREDICT · DISPATCH · RESTORE</div><h2>让每一度光伏电，<br>找到更合适的去向。</h2><p>预测发电与用电的变化，协调消纳、储存和外送；识别污染损失，联动无人机复核与机器人清扫。</p><div class="hero-bottom"><span>01 概率预测</span><span>02 风险调配</span><span>03 智能运维</span></div></div>${sceneSVG()}</section><div class="kpis">${kpi('日间预测误差 nRMSE',num(m.nrmse,2),'%','公开实测回放 · 257个日间样本','blue')}${kpi('相较持续性误差降低',num((1-m.rmse/mp.rmse)*100),'%','相对改善 · 按日块检验','green')}${kpi('同设备调配成本降低',num(s.rule_cost_reduction),'%','5日离线回放 · 3日未优于规则','gold')}${kpi('90%预测区间覆盖',num(coverage(b.test.filter(r=>r.day),.9)),'%','验证集校准 · 测试集评价','red')}</div><div class="grid wide-left">${panel('源—荷—储协同态势','当前环境情景 · 15分钟分辨率',lineChart({labels:x.input.map(r=>r.label),series:[{name:'光伏可用出力',values:x.input.map(r=>r.pv),color:C.gold},{name:'生产负荷',values:x.input.map(r=>r.load),color:C.gray},{name:'购电功率',values:x.rolling.rows.map(r=>r.import),color:C.blue}],unit:'功率 / 千瓦'}),`<b>情景分析：</b>日光伏${num(x.rolling.balance.pv)}千瓦时，负荷${num(x.rolling.balance.load)}千瓦时；滚动策略需从电网补充${num(x.rolling.balance.import)}千瓦时。曲线来自可调物理情景，不代表实时现场遥测。`,'dispatch')}${panel('当前建议与行动','先判断条件，再形成任务',insight('01','用预测区间管理出力风险','预测中位数之外，结合区间宽度确定储能余量；复杂天气下保留固定规则作为回退。','查看预测证据','forecast')+insight('02',`优先复核${Array.from({length:48},(_,i)=>i).filter(i=>loss(i)>10).length}个高损失分区`,'合成风险图只用于流程演练。卫星筛查后应由无人机与参考板验证，再触发清扫。','查看污染分布','remote')+insight('03',cfg.wind>8?'强风条件下暂停无人机':'当前天气允许规划巡检',`环境风速${num(cfg.wind)}米/秒，降雨${num(cfg.rain)}毫米/小时；任务执行受天气与电量联锁。`,'编排协同任务','operations'))}</div><div class="step-flow">${[['chart','预测发电与负荷','提前1小时预测，观察误差和区间覆盖。','forecast'],['battery','安排储存与消纳','同容量规则对照，核对每日电能平衡。','dispatch'],['sat','定位污染与损失','光谱、空间和电参数交叉验证。','remote'],['drone','协同作业与复测','无人机复核、机器人清扫、效益归档。','operations']].map(([ic,t,d,p],i)=>`<div class="step-card"><div class="number">0${i+1} / ${icon(ic)}</div><h3>${t}</h3><p>${d}</p><button class="btn small" data-page="${p}">进入模块 →</button></div>`).join('')}</div>`+note('证据口径：预测和5日调配回放使用公开功率数据；环境推演、光谱图和设备任务使用合成数据。Chronos-2与HyperSIGMA属于拟验证模型，尚未形成该厂现场性能结论。','blue');}
function coverage(rows,alpha,model='pred'){const q=b.quantilesByModel[model][String(alpha)]*b.capacity;return mean(rows.map(r=>r.actual>=Math.max(0,r[model]-q)&&r.actual<=Math.min(b.capacity,r[model]+q)?1:0))*100;}
function forecast(){const {r,m,baseline}=selectedMetrics(),all=forecastDay==='all'?b.test:b.test.filter(r=>r.time.startsWith(forecastDay)),q=b.quantilesByModel[forecastModel][String(confidence)]*b.capacity,dates=[...new Set(b.test.map(r=>r.time.slice(0,10)))],e=r.map(x=>x[forecastModel]-x.actual),groups=dates.map(d=>r.filter(x=>x.time.startsWith(d))).filter(x=>x.length),ci=skillCI(groups),cover=coverage(r,confidence,forecastModel),meanWidth=mean(r.map(x=>Math.min(b.capacity,x[forecastModel]+q)-Math.max(0,x[forecastModel]-q)));
 return heading('PROBABILISTIC FORECASTING','概率预测与模型评价','先看预测是否可靠，再判断它能否支持调配。',`<button class="btn" data-action="export-forecast">${icon('download')} 导出预测</button><button class="btn primary" data-action="recompute">重新推理基线</button>`)+`<div class="kpis">${kpi('日间 nRMSE',num(m.nrmse,2),'%',`持续性 ${num(baseline.nrmse,2)}%`,'blue')}${kpi('平均绝对误差 MAE',num(m.mae,2),'千瓦',`评估样本 ${m.n} 条`)}${kpi(`${num(confidence*100,0)}%区间实际覆盖`,num(cover),'%',`平均区间宽度 ${num(meanWidth)} 千瓦`,'green')}${kpi('平均偏差',num(m.bias,2),'千瓦',m.bias<0?'整体存在低估倾向':'整体存在高估倾向','gold')}</div>`+panel('预测曲线与不确定性','公开实测功率 · 提前1小时 · 时间为源数据时钟',`<div class="row between" style="margin-bottom:15px"><div class="row"><label class="field">评估时段<select id="forecast-day">${['all',...dates].map(d=>`<option value="${d}" ${d===forecastDay?'selected':''}>${d==='all'?'全部测试日期':d}</option>`).join('')}</select></label><label class="field">已验证模型<select id="forecast-model"><option value="pred" ${forecastModel==='pred'?'selected':''}>深层MLP</option><option value="ridge" ${forecastModel==='ridge'?'selected':''}>岭回归</option><option value="persist" ${forecastModel==='persist'?'selected':''}>持续性</option></select></label><label class="field">名义区间覆盖<select id="confidence">${[.8,.9,.95].map(v=>`<option value="${v}" ${v===confidence?'selected':''}>${v*100}%</option>`).join('')}</select></label></div><span class="tag green">${forecastModel==='pred'?'已训练MLP':forecastModel==='ridge'?'已训练线性对照':'无需训练基线'}</span></div>${lineChart({labels:all.map(x=>forecastDay==='all'?x.time.slice(5,10):x.time.slice(11,16)),series:[{name:'实测功率',values:all.map(x=>x.actual),color:C.gray},{name:'模型预测',values:all.map(x=>x[forecastModel]),color:C.red}],unit:'功率 / 千瓦',height:270,band:{lo:all.map(x=>Math.max(0,x[forecastModel]-q)),hi:all.map(x=>Math.min(b.capacity,x[forecastModel]+q)),name:`${num(confidence*100,0)}%校准区间`}})}`,`<b>曲线解读：</b>区间越宽意味着决策不确定性越高；本时段覆盖${num(cover)}%，需要同时结合区间宽度${num(meanWidth)}千瓦判断。日间指标排除低辐照样本，全曲线仍展示夜间。${forecastDay==='2020-06-17'?'该日期为不完整测试日，不用于日调配总量对比。':''}`,'mlp')+`<div class="grid equal" style="margin-top:20px">${panel('预测一致性','日间实际值与预测值散点',scatter(r.map(x=>x.actual),r.map(x=>x[forecastModel])),`<b>分析：</b>点越接近对角线，一致性越高。决定系数R²=${m.r2===null?'不适用':num(m.r2,3)}；高出力样本的离散提示云量变化或特征不足。`)}${panel('残差分布与系统偏差','残差 = 预测 − 实际',histogram(e),`<b>分析：</b>平均残差${num(m.bias,2)}千瓦，${m.bias<0?'偏向低估':'偏向高估'}。95%经验残差范围为${num(quantile(e,.025))}至${num(quantile(e,.975))}千瓦；该范围不是均值置信区间。`)}</div><div class="grid equal">${panel('区间校准检查','使用验证集残差分位数，测试集计算覆盖',lineChart({labels:['50%','60%','70%','80%','90%','95%'],series:[{name:'名义覆盖率',values:[50,60,70,80,90,95],color:C.gold,dash:true},{name:'测试覆盖率',values:[.5,.6,.7,.8,.9,.95].map(a=>coverage(r,a,forecastModel)),color:C.blue}],unit:'覆盖率 / %',height:215}),`<b>分析：</b>曲线偏离一致线说明区间存在失配；调高名义覆盖率通常会增加区间宽度。漂移后应使用新的独立校准窗口。`)}${panel('逐日误差与稳健性','保留困难日期，避免只展示最佳日',bars({labels:groups.map(g=>g[0].time.slice(5,10)),series:[{name:'持续性nRMSE',values:groups.map(g=>metrics(g.map(x=>x.actual),g.map(x=>x.persist)).nrmse),color:C.gray},{name:'当前模型nRMSE',values:groups.map(g=>metrics(g.map(x=>x.actual),g.map(x=>x[forecastModel])).nrmse),color:C.red}],unit:'nRMSE / %',height:215}),`<b>按日块Bootstrap：</b>相对RMSE改善95%探索性区间 ${num(ci[0])}%—${num(ci[1])}%，重采样2000次、${groups.length}个日期块。日期少且末日不完整，不能作为全年可靠性证明。`)}</div>`+panel('模型对照与训练收敛','相同数据切分、相同日间评估口径',`<div class="grid equal no-margin"><div>${table(['模型','nRMSE','nMAE','R²'],[['persist','持续性'],['ridge','岭回归'],['pred','深层MLP']].map(([key,name])=>{let z=metrics(r.map(x=>x.actual),r.map(x=>x[key]));return [name,num(z.nrmse,2)+'%',num(z.nmae,2)+'%',z.r2===null?'—':num(z.r2,3)];}))}<p class="muted" style="font-size:11px;margin-top:12px">岭回归在完整测试集的MAE略优于MLP，模型选型应结合业务代价。</p></div><div>${lineChart({labels:b.history.filter((_,i)=>i%5===0).map(x=>String(x[0])),series:[{name:'训练损失',values:b.history.filter((_,i)=>i%5===0).map(x=>x[1]),color:C.blue},{name:'验证MSE',values:b.history.filter((_,i)=>i%5===0).map(x=>x[2]),color:C.red}],unit:'归一化损失',autoScale:true,height:200})}<small class="muted">最优验证轮次 ${b.bestEpoch}；横轴：训练轮次</small></div></div>`,`<b>结论：</b>公开基线具备可运行性；跨季节与本地复杂天气能力仍需验证。前沿模型的新增价值应通过同口径对比和消融实验确认。`,'chrono');}
function skillCI(groups){if(!groups.length)return [0,0];let seed=42,rng=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};const a=groups.map(g=>[sum(g.map(r=>(r[forecastModel]-r.actual)**2)),sum(g.map(r=>(r.persist-r.actual)**2))]);const skills=Array.from({length:2000},()=>{let x=0,y=0;for(let i=0;i<a.length;i++){let z=a[Math.floor(rng()*a.length)];x+=z[0];y+=z[1];}return y?100*(1-Math.sqrt(x/y)):0;});return [quantile(skills,.025),quantile(skills,.975)];}
const presets={clear:{...defaults,cloud:.08,dust:4,temp:30,wind:3},dust:{...defaults,cloud:.15,dust:14,temp:34,wind:11},cloud:{...defaults,cloud:.75,dust:6,temp:25,wind:5},hot:{...defaults,cloud:.05,dust:9,temp:44,wind:4}};
function configForm(){const defs=[['capacity','光伏容量','千瓦峰值',0,100000,.1],['battery','储能容量','千瓦时',0,100000,10],['batteryPower','储能功率','千瓦',0,50000,5],['exportLimit','外送上限','千瓦',0,50000,5],['temp','环境温度','℃',-30,75,1],['wind','风速','米/秒',0,40,.5],['dust','污染损失','%',0,50,1],['cloud','云量系数','0–1',0,1,.05],['rain','降雨强度','毫米/小时',0,30,.1],['loadScale','生产负荷倍率','倍',.1,10,.1],['risk','风险保守程度','0–1',0,1,.1],['deviceBattery','设备可用电量','%',0,100,1]];return `<div class="row" style="padding:0 22px 18px">${[['clear','晴天常规'],['dust','风沙污染'],['cloud','多云波动'],['hot','夏季高温']].map(([v,t])=>`<button class="btn small" data-preset="${v}">${t}</button>`).join('')}<span class="muted" style="font-size:11px">预设载入后可继续自定义</span></div><form id="scenario-form"><div class="controls">${defs.map(([k,t,u,min,max,step])=>`<label class="field">${t} / ${u}<input type="number" name="${k}" value="${cfg[k]}" min="${min}" max="${max}" step="${step}" required></label>`).join('')}</div><div class="toolbar"><p>同设备规则、滚动调配与无储能分别核算；按当日末储能闭合。</p><button class="btn primary" type="submit">计算自定义方案 ${icon('arrow')}</button></div></form>`;}
function dispatchPage(){const x=compute(),r=x.rolling.balance,f=x.rule.balance,n=x.none.balance,gain=f.cost?100*(f.cost-r.cost)/f.cost:0,pay=r.pv-r.curtail;
 return heading('ENERGY DISPATCH WORKBENCH','储能调配与日电能平衡','推荐策略与自定义环境并行比较，以同设备增量作为算法收益依据。',`<button class="btn" data-action="export-dispatch">${icon('download')} 导出调配表</button><button class="btn soft" data-action="dispatch-recommend">生成建议方案</button>`)+`<div class="kpis">${kpi('日光伏发电量',num(r.pv),'千瓦时','物理合成情景','gold')}${kpi('滚动方案光伏接受率',num(r.utilization),'%',`已接受 ${num(pay)} 千瓦时`,'green')}${kpi('同设备成本改善',num(gain),'%',gain>=0?'相较固定规则策略':'当前未优于固定规则','red')}${kpi('日电能平衡残差',num(Math.abs(r.residual),5),'千瓦时',`终端SOC ${cfg.battery?num(x.rolling.finalEnergy/cfg.battery*100):'0'}%`,'blue')}</div>`+`<section class="panel" style="margin-bottom:20px"><header class="panel-head"><div><h2>外部环境与设备配置</h2><p>所有方案共享相同环境；修改后点击计算，图表与建议同步更新。</p></div>${detail('dispatch')}</header>${configForm()}</section>`+`<div class="grid wide-left">${panel('日内功率调配','滚动方案 · 15分钟分辨率',lineChart({labels:x.input.map(r=>r.label),series:[{name:'光伏',values:x.input.map(r=>r.pv),color:C.gold},{name:'负荷',values:x.input.map(r=>r.load),color:C.gray},{name:'充电',values:x.rolling.rows.map(r=>r.charge),color:C.green},{name:'放电',values:x.rolling.rows.map(r=>r.discharge),color:C.red},{name:'购电',values:x.rolling.rows.map(r=>r.import),color:C.blue}],unit:'功率 / 千瓦',height:255}),`<b>分析：</b>充放电按分时电价、预测富余与终端SOC共同决定；具体执行时段见下方分时计划。当前外送上限${num(cfg.exportLimit)}千瓦，弃光${num(r.curtail)}千瓦时；生产负荷由光伏、储能与购电共同满足。`)}${panel('方案建议与适用条件','由本次计算和设备约束自动生成',dispatchAdvice(x))}</div><div class="grid equal">${panel('储能状态与日终闭合','规则与滚动方案相同初始/终端SOC',lineChart({labels:[...x.input.map(r=>r.label),'24:00'],series:[{name:'滚动SOC',values:[...x.rolling.rows.map(r=>cfg.battery?r.energy/cfg.battery*100:0),cfg.battery?x.rolling.finalEnergy/cfg.battery*100:0],color:C.red},{name:'固定规则SOC',values:[...x.rule.rows.map(r=>cfg.battery?r.energy/cfg.battery*100:0),cfg.battery?x.rule.finalEnergy/cfg.battery*100:0],color:C.gray}],unit:'SOC / %',height:220}),`<b>约束：</b>SOC范围10–90%，初始/终端50%；充放电效率各95%。状态离散可能使小容量储能保守，应在工程优化器中细化。`)}${panel('三种方案的成本与弃光','无储能与同设备基线分列',bars({labels:['无储能','固定规则','滚动调配'],series:[{name:'日运行成本',values:[n.cost,f.cost,r.cost],color:C.red}],unit:'成本 / 元',height:220}),`<b>比较：</b>相对无储能节省${num(n.cost-r.cost)}元，包含储能设备价值；相对同设备规则节省${num(f.cost-r.cost)}元，才是本情景算法增量。`)}</div>`+dispatchAnalysisView(x,cfg)+panel('每日储存与消耗电能核对','交流侧电量 · 分开列示电池吞吐与系统边界',table(['能量项','滚动方案 / 千瓦时','核算说明'],[['光伏发电',num(r.pv),'系统输入'],['电网购电',num(r.import),'系统输入'],['生产消耗',num(r.load),'系统输出'],['外送电量',num(r.export),'系统输出'],['弃光电量',num(r.curtail),'未利用的可用光伏'],['储能充电 / 放电',`${num(r.charge)} / ${num(r.discharge)}`,'内部吞吐，不重复计为输入输出'],['储能损耗',num(r.loss),'充电量 − 放电量 − 储能变化'],['储能变化',num(r.storageDelta,5),'期末 − 期初'],['平衡残差',num(r.residual,7),'光伏 + 购电 − 生产 − 外送 − 弃光 − 损耗 − 储能变化']]),`<b>口径：</b>光伏接受率=1−弃光/光伏，包含进入储能的电量；终端实际可用绿电还需扣除储能损耗。电池可从电网充电，不能把全部放电量当作光伏消纳。`)+`<div style="margin-top:20px">${publicDispatchPanel()}</div>`;
}
function dispatchAdvice(x){const r=x.rolling.balance,f=x.rule.balance;return insight('01',r.cost<f.cost?'优先采用滚动方案参与试验':'本情景优先保留固定规则',`滚动成本${num(r.cost)}元，规则成本${num(f.cost)}元。${r.cost<f.cost?'建议先影子运行并按天气分层复核增益。':'风险折减和状态离散可能降低收益，不应默认复杂算法一定更好。'}`)+insight('02',cfg.dust>8?'先复核污染，再安排清扫':'按净收益阈值安排清扫',`假设污染损失${num(cfg.dust)}%；${cfg.wind>8?'当前风速超过无人机演练阈值，可等待风速降低。':'可规划无人机复核，清扫后对归一化功率复测。'}`)+insight('03','保护生产负荷与储能边界',`本方案假设电网可补足缺电；实际接入还需配置变压器、线路与生产设备约束。${cfg.battery===0?'当前储能容量为零，滚动与无储能结果应一致。':''}`);}
function publicDispatchPanel(){return panel('公开数据：5日调配回放','离线连续LP滚动策略 · 与上方合成DP情景分开',bars({labels:replay.days.map(r=>r.date.slice(5)),series:[{name:'同设备规则',values:replay.days.map(r=>r.rule_cost),color:C.gray},{name:'预测驱动滚动',values:replay.days.map(r=>r.mpc_cost),color:C.red},{name:'理想已知出力',values:replay.days.map(r=>r.oracle_cost),color:C.gold}],unit:'日成本 / 元',height:220}),`<b>证据：</b>同设备成本合计下降${num(replay.stats.rule_cost_reduction)}%，但5天中有3天未优于规则；理想已知出力仅作性能上界，不能作为可实现收益。采油厂本地效果需更长周期验证。`);}
function remote(){const x=compute(),a=Array.from(selected),avg=mean(a.map(loss)),energy=sum(x.input.map(r=>r.pv))*.25*a.length/48,benefit=cleaningBenefit({energy:energy*14,before:avg,after:1,value:cfg.energyValue,cost:cfg.cleanCost}),wave=Array.from({length:81},(_,i)=>400+i*2100/80),labels=wave.map(w=>num(w,0)),soil=loss(remoteChoice)/100;
 return heading('SPECTRAL & SPATIAL INTELLIGENCE','遥感监测与污染损失评估','卫星筛查区域，无人机定位异常，地面参考板复核污染类型。',`<button class="btn" data-action="select-high">选择高损失区域</button><button class="btn primary" data-action="to-operations">规划复核与清扫 ${icon('arrow')}</button>`)+note('当前阵列风险图、光谱曲线与污染损失均为合成情景；未接入卫星或无人机影像，未运行HyperSIGMA污染分类。卫星单次观测不能替代单板连续监测。','blue')+`<div class="kpis">${kpi('待复核高损失分区',Array.from({length:48},(_,i)=>i).filter(i=>loss(i)>10).length,'个','污染损失假设 >10%','red')}${kpi('已选分区',a.length,'个','点击阵列图可增减','blue')}${kpi('已选平均污染损失',num(avg),'%','待现场归一化功率验证','gold')}${kpi('演练已清扫分区',cleared.length,'个','任务完成后更新标记','green')}</div><div class="grid wide-left">${panel('阵列污染风险分布','点击选择作业区域 · 再次点击取消',`<div class="row between"><span class="tag">合成分区图</span><div class="row"><button class="btn small" data-action="select-all">全选</button><button class="btn small" data-action="clear-selection">取消选择</button></div></div>${arrayMap()}<p class="muted" style="font-size:11px;margin-top:12px">最近查看：A${String(remoteChoice+1).padStart(2,'0')}，污染损失假设${num(loss(remoteChoice))}%。颜色表达损失分级，不表示实测识别置信度。</p>`,`<b>分析：</b>优先复核高损失、连续聚集的区域；不能只靠反射率异常判定蒙尘，应排除阴影、镜面反射、热斑与组串故障。`,'hyper')}${panel('已选区域的清扫价值','按未来14天可兑现电量估计',`<div class="metric-list"><div class="mini-metric"><span>14天蒙尘电量 / 千瓦时</span><strong>${num(energy*14,0)}</strong></div><div class="mini-metric"><span>恢复电量 / 千瓦时</span><strong>${num(benefit.extraEnergy,0)}</strong></div><div class="mini-metric"><span>增量清扫成本 / 元</span><strong>${num(cfg.cleanCost,0)}</strong></div><div class="mini-metric"><span>预计净收益 / 元</span><strong class="${benefit.net>=0?'green':'red'}">${num(benefit.net,0)}</strong></div></div><div style="margin-top:16px">${insight('01',benefit.net>0?'建议现场复核后清扫':'建议等待损失积累或降低清扫成本',`${a.length}个区域，平均损失${num(avg)}%，假设清扫后剩余1%；电量兑现价值${num(cfg.energyValue,2)}元/千瓦时。`)}${insight('02','清扫后的验收依据','在相似辐照与温度下比较清洁率和组串出力，记录停机、清扫耗能及后续再积尘。')}</div>`,`<b>边界：</b>所选分区等容量；14天重复当前典型日；兑现价值应扣除无法消纳和外送限制，清扫成本应包含巡检与停机。`,'robot')}</div><div class="grid equal">${panel('清洁与污染光谱响应','线性混合机理示意 · 非卫星实测反射率',lineChart({labels,series:[{name:'清洁板参考',values:wave.map(w=>spectralMix(w,0)),color:C.blue},{name:`污染分区A${String(remoteChoice+1).padStart(2,'0')}`,values:wave.map(w=>spectralMix(w,soil)),color:C.red},{name:'尘土端元',values:wave.map(w=>spectralMix(w,1)),color:C.gold}],unit:'反射率 / 无量纲',height:230}),`<b>分析：</b>展示400—2500纳米范围的合成光谱。污染丰度与功率损失不是天然一一对应关系，需要现场标定；水汽吸收区与坏波段应剔除。`,'hyper')}${panel('污染造成的可恢复出力','固定气象条件比较清洁与蒙尘状态',lineChart({labels:x.input.map(r=>r.label),series:[{name:'清洁参考出力',values:x.input.map(r=>r.clean*.99),color:C.green},{name:'当前污染出力',values:x.input.map(r=>r.pv),color:C.gold}],unit:'功率 / 千瓦',height:230}),`<b>分析：</b>全场假设损失${num(cfg.dust)}%降至1%时，相对发电恢复${num(((.99/(1-cfg.dust/100))-1)*100)}%。这是相同气象下的反事实情景，不是清扫设备现场增益。`)}</div>`+panel('多源证据与复核建议','将异常检测转为可执行的检查顺序',table(['观测组合','可能原因','建议动作'],[['光谱改变 + 归一化功率持续下降','蒙尘、结垢或表面老化','无人机近场复核，参考板校准，局部清扫后复测'],['热红外局部升温 + 电参异常','热斑、电气连接或旁路异常','转电气检修，避免只做清扫'],['周期性低出力 + 明显遮挡边界','阴影或周边遮挡','核对太阳角与遮挡源，调整运维方案'],['区域普遍减发 + 天气同步变化','辐照变化或预报偏差','优先修正气象与预测，不盲目派机器人']]),`<b>技术路线：</b>空间—光谱基础模型提取特征，污染状态进入预测适配器；清扫前后反事实出力用于判断作业价值，形成预测与运维闭环。`,'hyper');}
let opcfg={altitude:60,speed:4,overlap:75,robotSpeed:6,...stored.opcfg};
function currentPlan(){let p={drone:planOperations({...cfg,deviceBattery:levels.drone},[...selected]).drone,robot:planOperations({...cfg,deviceBattery:levels.robot},[...selected]).robot},factor=60/opcfg.altitude*4/opcfg.speed*(100-75)/(100-opcfg.overlap);p.drone.minutes=Math.ceil((p.drone.minutes-8)*factor+8);p.drone.battery=Math.ceil(p.drone.minutes*.65);p.robot.minutes=Math.ceil((p.robot.minutes-10)*6/opcfg.robotSpeed+10);p.robot.battery=Math.ceil(p.robot.minutes*.45);if(p.drone.battery+20>levels.drone){p.drone.allowed=false;p.drone.reasons.push('预计耗电后不足20%返航余量');}if(p.robot.battery+15>levels.robot){p.robot.allowed=false;p.robot.reasons.push('预计耗电后不足15%返站余量');}return p;}
function routeSVG(route){const pts=route.map(i=>[43+i%8*51,35+Math.floor(i/8)*42]);return `<div class="route-view"><svg viewBox="0 0 450 285" role="img" aria-label="无人机分区覆盖航线示意">${Array.from({length:48},(_,i)=>`<rect x="${25+i%8*51}" y="${19+Math.floor(i/8)*42}" width="36" height="28" rx="2" fill="${selected.has(i)?'#c8b188':'#dce1de'}" stroke="#bec6c0"/><text x="${43+i%8*51}" y="${37+Math.floor(i/8)*42}" text-anchor="middle" font-size="8" fill="#69736c">${i+1}</text>`).join('')}<polyline points="${[[12,273],...pts,[12,273]].map(p=>p.join(',')).join(' ')}" fill="none" stroke="${C.red}" stroke-width="1.7" stroke-dasharray="5 3"/>${pts.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="${C.red}"/><text x="${x+6}" y="${y-8}" font-size="8" fill="#923945">${i+1}</text>`).join('')}<circle cx="12" cy="273" r="6" fill="${C.green}"/><text x="26" y="277" font-size="9" fill="#66766b">起降 / 返航点（局部坐标）</text></svg></div>`;}
function operations(){let p=currentPlan(),active=tasks.filter(t=>['planned','running','paused'].includes(t.status)).length;return heading('UAV & ROBOT ORCHESTRATION','无人机与机器人协同作业','从推荐方案到自定义部署，以环境联锁约束每一步任务。',`<button class="btn" data-action="export-mission">${icon('download')} 导出作业方案</button><button class="btn primary" data-action="auto-mission">生成推荐方案</button>`)+note('设备未连接：当前提供本地任务演练、状态推进和方案导出，不向真实无人机或机器人下发指令。实际部署需接入设备SDK、地理坐标、障碍物与作业许可。','blue')+`<div class="kpis">${kpi('已选择作业区域',selected.size,'个','可到遥感蒙尘模块调整','blue')}${kpi('风速 / 降雨',`${num(cfg.wind)} / ${num(cfg.rain)}`,'','米/秒 / 毫米/小时','gold')}${kpi('设备剩余电量',`${num(levels.drone,0)} / ${num(levels.robot,0)}`,'%','无人机 / 机器人独立电量','green')}${kpi('待完成任务',active,'项',`已完成 ${tasks.filter(t=>t.status==='completed').length} 项`)}</div><div class="grid equal">${panel('无人机复核部署','UAV-01 · 高光谱 / RGB / 热红外载荷示意',`<div class="device"><div class="device-icon">${icon('drone')}</div><div class="grow"><h3>区域定位与覆盖巡检</h3><p>蛇形分区覆盖 · 自动回到起降点</p></div><span class="tag ${p.drone.allowed?'green':'red'}">${p.drone.allowed?'允许演练':'条件不满足'}</span></div><div class="metric-list" style="margin:15px 0"><div class="mini-metric"><span>预计任务时间 / 分钟</span><strong>${p.drone.minutes}</strong></div><div class="mini-metric"><span>预计耗电 / 百分点</span><strong>${p.drone.battery}</strong></div></div>${p.drone.reasons.length?note(p.drone.reasons.join('；'),'red'):note('环境与电量检查通过；保留至少20%返航余量。','green')}<button class="btn primary" data-task-create="drone" ${p.drone.allowed?'':'disabled'}>部署无人机巡检演练</button>`,`<b>建议：</b>${cfg.wind>8?'等待风速降至8米/秒以下；可先执行地面诊断。':cfg.cloud>.5?'多云时重点记录辐照变化，避免跨光照条件直接比较反射率。':'优先巡检高损失分区，获取可与组串出力配准的影像。'}`,'robot')}${panel('清扫机器人部署','ROBOT-01 · 干式清扫与清扫后复测',`<div class="device"><div class="device-icon">${icon('robot')}</div><div class="grow"><h3>按区域清扫与回站</h3><p>收益阈值筛选 · 清扫后复测</p></div><span class="tag ${p.robot.allowed?'green':'red'}">${p.robot.allowed?'允许演练':'条件不满足'}</span></div><div class="metric-list" style="margin:15px 0"><div class="mini-metric"><span>预计任务时间 / 分钟</span><strong>${p.robot.minutes}</strong></div><div class="mini-metric"><span>预计耗电 / 百分点</span><strong>${p.robot.battery}</strong></div></div>${p.robot.reasons.length?note(p.robot.reasons.join('；'),'red'):note('干式清扫条件通过；保留至少15%返站余量。','green')}<button class="btn primary" data-task-create="robot" ${p.robot.allowed?'':'disabled'}>部署机器人清扫演练</button>`,`<b>建议：</b>${cfg.rain>0?'降雨期间禁止干式清扫。':cfg.temp>40?'优先安排早晚低温窗口，作业前核对板面温度。':'先进行小区块清扫验证，再扩大范围；高风险电气异常转检修。'}`,'robot')}</div><div class="grid equal">${panel('自定义作业方案','自定义参数用于估算时间与电量，非设备性能认证',`<form id="operation-form"><div class="controls" style="grid-template-columns:1fr 1fr;padding:0 0 18px">${[['altitude','无人机高度 / 米',30,100,5],['speed','巡检速度 / 米/秒',1,8,.5],['overlap','影像重叠率 / %',60,90,5],['robotSpeed','清扫速度 / 米/分钟',2,12,1]].map(([k,t,min,max,step])=>`<label class="field">${t}<input name="${k}" type="number" min="${min}" max="${max}" step="${step}" value="${opcfg[k]}" required></label>`).join('')}</div><div class="row"><button class="btn primary" type="submit">更新自定义方案</button><button class="btn" data-page="dispatch" type="button">调整天气与设备条件</button></div></form><div class="subheading">方案效果对比</div>${bars({labels:['无人机巡检','机器人清扫'],series:[{name:'当前方案耗时',values:[p.drone.minutes,p.robot.minutes],color:C.red}],unit:'分钟',height:190})}`,`<b>分析：</b>更低高度、更高重叠率和更慢速度将增加巡检耗时与电量。应在识别精度与覆盖效率之间平衡，当前估算参数需用实际设备标定。`)}${panel('巡检航线与任务范围','所选分区按行蛇形访问，导出局部区域编号',routeSVG(p.drone.route),`<b>路线：</b>${selected.size}个分区，起降点闭合；仅展示拓扑顺序，未包含真实地理路径、避障和禁飞区。`,'robot')}</div><div class="grid equal">${panel('任务队列与部署状态','状态保存在当前浏览器，可暂停、继续和终止',tasks.length?tasks.slice().reverse().map(taskCard).join(''):`<div class="empty">还没有任务。上方选择无人机或机器人部署演练。</div>`,`<b>联锁：</b>开始或推进任务前再次检查环境与电量；环境变化可能触发暂停。演练“推进一步”不表示设备遥测。`)}${panel('作业日志与复核闭环','演练操作留痕，支持报告导出',`<div class="task-log">${logs.length?logs.slice(-18).map(t=>`<div>${esc(t)}</div>`).join(''):'尚无操作记录。'}</div><div style="margin-top:15px">${insight('01','无人机完成后','将异常区、影像定位与污染类型交给现场复核；没有现场真值时不能自动确认蒙尘。')}${insight('02','机器人完成后','演练标记对应分区为已清扫。真实恢复电量必须通过归一化出力和对照区验证。')}</div>`)}</div>`;}
const statusMap={planned:'待开始',running:'运行演练',paused:'已暂停',completed:'已完成演练',cancelled:'已终止'};
function taskCard(t){return `<div class="task-card"><header><b>${t.type==='drone'?'无人机巡检':'机器人清扫'} · ${esc(t.id)}</b><span class="tag ${t.status==='completed'?'green':t.status==='paused'?'red':''}">${statusMap[t.status]||'状态未知'}</span></header><p>${t.regions.length}个区域 · 预计${t.minutes}分钟 · ${esc(t.created)}</p><div class="progress"><i style="width:${t.progress}%"></i></div><div class="row between"><small class="muted">演练进度 ${t.progress}%</small><small class="muted">${t.progress===100?'待现场复测':'设备遥测未接入'}</small></div><div class="task-actions">${t.status==='planned'?`<button class="btn small primary" data-task="${t.id}" data-event="start">开始演练</button>`:''}${t.status==='running'?`<button class="btn small primary" data-task="${t.id}" data-event="step">推进一步</button><button class="btn small" data-task="${t.id}" data-event="pause">暂停</button>`:''}${t.status==='paused'?`<button class="btn small" data-task="${t.id}" data-event="resume">继续</button>`:''}${['planned','running','paused'].includes(t.status)?`<button class="btn small danger" data-task="${t.id}" data-event="cancel">终止</button>`:''}</div></div>`;}
function benefits(){const s=replay.stats,x=compute(),daily=s.upgrade_mean_saving,baseAnnual=daily*financial.days*financial.realization/100,cf=baseAnnual-financial.annualOpex*10000,I=financial.investment*10000,r=financial.discount/100,annuity=sum(Array.from({length:financial.years},(_,i)=>1/(1+r)**(i+1))),npv=-I+cf*annuity,threshold=(I/annuity+financial.annualOpex*10000)/financial.days,points=Array.from({length:financial.years+1},(_,i)=>-I+cf*sum(Array.from({length:i},(_,j)=>1/(1+r)**(j+1)))),clean=cleaningBenefit({energy:x.rolling.balance.pv*14,before:cfg.dust,after:1,value:cfg.energyValue,cost:cfg.cleanCost}),minutes=48*8,robot=48*3+10;
 return heading('VALUE & ECONOMIC EVIDENCE','效益分析与联合试点价值','把算法增量、储能价值与污染恢复分开核算，展示收益边界。',`<button class="btn" data-action="export-report">${icon('download')} 导出分析报告</button>`)+`<div class="kpis">${kpi('同设备日均节省',num(daily,2),'元','5个公开回放日，非全年保证','blue')}${kpi('假设年净现金流',num(cf/10000,3),'万元',`按${financial.days}等效日与当前兑现率`,'gold')}${kpi('算法升级净现值',num(npv/10000,2),'万元',`${financial.years}年 / 折现率${financial.discount}%`)}${kpi('盈亏平衡日毛收益',num(threshold,1),'元/日','需覆盖投入与年运维','green')}</div>`+note('当前公开短期样本下，默认算法升级投入假设的经济性不足。适合共享平台、小规模试点，先确认本地收益；不能将新增储能价值重复计入算法收益。',npv<0?'red':'green')+`<div class="grid equal">${panel('实际样本：算法收益逐日分布','规则成本 − 滚动成本，保留负收益日',bars({labels:replay.days.map(d=>d.date.slice(5)),series:[{name:'同设备增量节省',values:replay.days.map(d=>d.upgrade_saving),color:C.red}],unit:'元 / 日',height:225}),`<b>分析：</b>5日有3日为负；总成本下降${num(s.rule_cost_reduction)}%，收益集中于部分日期。应分析天气、预报误差和电价时段，而非只报告平均改善。`,'economy')}${panel('年现金流与折现回收','按相同年收益假设外推，未计税和融资',lineChart({labels:points.map((_,i)=>`第${i}年`),series:[{name:'累计折现现金流',values:points.map(x=>x/10000),color:npv>=0?C.green:C.red}],unit:'万元',ymin:Math.min(...points)/10000,height:225}),`<b>分析：</b>${npv<0?'本参数下评价期内未实现折现回收。':'本参数下可获得正净现值，但仍依赖收益兑现假设。'}日均收益需达到${num(threshold)}元，才足以支持当前投入规模。`)}</div>`+`<section class="panel" style="margin-bottom:20px"><header class="panel-head"><div><h2>经济参数与可兑现收益</h2><p>输入单位明确；收益兑现率属于情景假设，不是统计置信水平。</p></div>${detail('economy')}</header><form id="finance-form"><div class="controls">${[['investment','算法升级投入 / 万元',0,10000,.5],['annualOpex','年运维 / 万元',0,1000,.1],['days','等效运行日 / 天/年',1,366,1],['years','评价期 / 年',1,25,1],['discount','折现率 / %',0,30,.5],['realization','收益兑现率 / %',0,150,5]].map(([k,t,min,max,step])=>`<label class="field">${t}<input name="${k}" type="number" min="${min}" max="${max}" step="${step}" value="${financial[k]}" required></label>`).join('')}<label class="field">清扫成本 / 元/次<input name="cleanCost" type="number" min="0" max="100000" value="${cfg.cleanCost}" required></label><label class="field">可兑现电量价值 / 元/千瓦时<input name="energyValue" type="number" min="0" max="5" step=".01" value="${cfg.energyValue}" required></label></div><div class="toolbar"><p>已有光伏与储能作为沉没资产；算法升级投入单列。</p><button class="btn primary" type="submit">重算效益与敏感性</button></div></form></section>`+`<div class="grid equal">${panel('净现值敏感性矩阵','相同日均增益与运维假设，改变投入和兑现率',heatTable(['50%','70%','100%','130%'],['0.5万','2万','5万','10万'],[50,70,100,130].map(p=>[.5,2,5,10].map(inv=>-inv+(daily*financial.days*p/100-financial.annualOpex*10000)*annuity/10000))),`<b>分析：</b>共享设备与平台降低边际投入，可能比直接建设独立系统更可行。负净现值时应先提高可验证收益，或降低投入和运维。`)}${panel('污染恢复与清扫净收益','14天重复当前典型日 · 全场假设',bars({labels:['污染状态发电','清扫后可发电','恢复电量'],series:[{name:'14天电量',values:[x.rolling.balance.pv*14,x.rolling.balance.pv*14+clean.extraEnergy,clean.extraEnergy],color:C.gold}],unit:'千瓦时',height:220}),`<b>分析：</b>损失${num(cfg.dust)}%降至1%，相对恢复${num(clean.gainPct)}%，毛价值${num(clean.gross)}元，扣成本后${num(clean.net)}元。采用兑现电价反映可消纳电量，不直接叠加到调度收入。`)}</div><div class="grid equal">${panel('作业效率与部署规模','假设人工8分钟/分区，机器人3分钟/分区+10分钟准备',bars({labels:['人工作业','机器人作业'],series:[{name:'48分区预计耗时',values:[minutes,robot],color:C.blue}],unit:'分钟',height:200}),`<b>分析：</b>在这些假设下预计节省${num((1-robot/minutes)*100)}%时间。实际效率受面积、通道、换电、转场和污染附着影响，应按同面积实测工时验收。`,'robot')}${panel('系统优势与合作价值','围绕能验证、能接入、能交付组织联合试验',insight('01','把不确定性接入调配','用概率区间和天气分层识别风险，保留规则回退，降低复杂天气下失效影响。')+insight('02','把污染识别接入收益决策','用污染状态解释可恢复损失，按净收益和气象窗口选择清扫区域。')+insight('03','从边缘装置起步，再评估芯片化','先部署工业网关、通信接口与模型压缩；模型稳定后再评估NPU适配与专用硬件经济性。'))}</div>`+cooperation();}
function cooperation(){return panel('合作实施与验收路径','6个月联合试点 · 数据、算法与设备职责清晰',`<div class="milestones">${[['01 / 第1个月','数据接入与现场边界','油田：功率、气象、负荷、电价、储能和生产约束；建立清洁参考板。'],['02 / 第2–3个月','基线与前沿模型对照','算法团队：时序预测、污染标注、同口径比较、模块消融与漂移评估。'],['03 / 第4个月','影子调配与近场巡检','联合团队：只出建议，比较规则；设备企业：影像、网关和机器人接口联调。'],['04 / 第5个月','限定区域闭环验证','先经现场确认再作业，记录环境、任务、清扫成本及归一化功率恢复。'],['05 / 第6个月','联合验收与经济复核','连续90天分天气误差、区间覆盖、净收益、生产约束及任务完成率复核。'],['06 / 推广前','明确交付与权利边界','交付数据规范、模型包、接口、试验报告；约定知识产权、维护与数据权限。']].map(([i,t,d])=>`<div class="milestone"><small>${i}</small><b>${t}</b><p>${d}</p></div>`).join('')}</div>`,`<b>拟验收：</b>1小时日间nMAE≤5%作为研究目标；90%区间覆盖85–95%且约束区间宽度；污染F1≥0.90需独立盲测；同设备净收益为正、生产约束零违规。以上均为待验证目标。`);}
function lab(){const m=metrics(b.test.filter(x=>x.day).map(x=>x.actual),b.test.filter(x=>x.day).map(x=>x.pred));let uploadBody=uploaded?uploadResult():`<div class="empty">上传后自动校验时间与数值、计算误差并绘制实际/预测曲线。</div>`;
 return heading('DATA & MODEL LABORATORY','数据实验室与模型能力','公开数据可追溯，合成情景可复算，模型能力与研发设计明确区分。',`<a class="btn" href="./data/evaluation-template.csv" download>${icon('download')} 下载上传样例</a><button class="btn primary" data-action="interfaces">设备与数据接口</button>`)+`<div class="kpis">${kpi('公开原始数据时间跨度','34','天','2020-05-15至2020-06-17','blue')}${kpi('训练 / 验证 / 测试',b.split.map(x=>num(x,0)).join(' / '),'条','按目标时间严格切分','gold')}${kpi('日间测试 nRMSE',num(m.nrmse,2),'%','实际MLP权重与预测可下载','green')}${kpi('设备接入状态','未连接','','支持任务演练与接口方案')}</div><div class="grid equal">${panel('上传模型评价数据','支持UTF-8 CSV，本地解析，不上传服务器',`<label class="dropzone"><strong>选择实际值与预测值数据</strong><p>必需列：timestamp, actual_kw, pred_kw</p><input id="csv-upload" type="file" accept=".csv,text/csv" aria-label="上传模型评价CSV"></label><p class="muted" style="font-size:11px">功率单位：千瓦；时间：YYYY-MM-DDTHH:mm。最多20,000行、5MB。采用已有预测结果评估，不会自动训练基础模型。</p><div class="quality-row"><span>重复时间</span><b>拒绝并报告行号</b></div><div class="quality-row"><span>负功率、空值、非数值</span><b>拒绝并报告行号</b></div><div class="quality-row"><span>时间顺序</span><b>自动排序，不做未来插值</b></div>`,`<b>隐私：</b>上传文件只在当前浏览器内存中处理；刷新后清除。部署在GitHub Pages的系统没有私有数据服务端。`)}${panel('上传数据评价结果','上传误差按所有有效行计算，不与内置日间指标混用',uploadBody,uploaded?'容量归一化按当前场景容量；上传数据没有辐照字段，不自动应用内置日间筛选。':'支持误差指标、残差分布、预测曲线及评价结果下载。')}</div>${uploaded?panel('上传数据：误差与一致性','仅当前上传样本，未经独立训练协议验证',`<div class="grid equal no-margin"><div>${scatter(uploaded.map(x=>x.actual),uploaded.map(x=>x.pred),Math.max(cfg.capacity,1))}</div><div>${histogram(uploaded.map(x=>x.pred-x.actual))}</div></div>`):''}<div class="subheading">模型组件与能力状态</div><div class="model-grid">${modelList.map(([id,t,status,desc])=>`<article class="model-card"><div class="detail">${detail(id)}</div><span class="tag ${status.startsWith('已')||status.startsWith('可')?'green':'blue'}">${status}</span><h3 style="margin-top:13px">${t}</h3><p>${desc}</p></article>`).join('')}</div><div class="grid equal">${panel('数据清单与下载','数据与权重随仓库发布，便于复核',table(['数据','用途','获取'],[['公开单逆变器样本','训练/验证/测试，含缺测窗口','<a href="./data/public-source.csv" download>CSV ↧</a>'],['模型评价预测','点预测、对照与验证残差','<a href="./data/benchmark.json" download>JSON ↧</a>'],['实际MLP权重','浏览器推理与离线复算','<a href="./data/model.json" download>JSON ↧</a>'],['5日离线调配结果','同设备规则与滚动对照','<a href="./data/replay-dispatch.json" download>JSON ↧</a>'],['当前环境与作业方案','合成数据及本地演练参数','<button class="btn small" data-action="export-mission">导出JSON</button>']] ),`<b>来源与使用：</b>公开数据为Kaggle Solar Power Generation Data的Plant 1；当前选取单逆变器。容量映射与负荷、储能、电价假设见模型详情。完整出处与许可链接保留在仓库数据说明中。`)}${panel('数据接入与部署条件','把当前研究平台转为现场系统所需的输入',table(['对象','最小数据','质量约束'],[['光伏与负荷','时间、设备ID、交流功率、电量','统一时区、15分钟或更高频、可追溯缺失'],['气象与预报','辐照、板温、风速、预报发布时间','保留历史预报版本，禁止未来信息泄漏'],['遥感与巡检','辐射校正影像、坐标、清洁参考板','阵列/地块隔离验证，核对分辨率'],['储能与机器人','SOC、功率限制、状态、任务ID','设备权限、互锁、急停与审计']]),`<b>工程路线：</b>先用工业网关接入与影子运行，再做限定区域闭环；GitHub Pages作为可共享的前端与研究演示，真实训练和设备控制部署在受控服务端。`)}</div>`+cooperation();}
function uploadResult(){let m=metrics(uploaded.map(x=>x.actual),uploaded.map(x=>x.pred),cfg.capacity);return `<div class="metric-list"><div class="mini-metric"><span>有效记录 / 条</span><strong>${m.n}</strong></div><div class="mini-metric"><span>RMSE / 千瓦</span><strong>${num(m.rmse,2)}</strong></div><div class="mini-metric"><span>MAE / 千瓦</span><strong>${num(m.mae,2)}</strong></div><div class="mini-metric"><span>平均偏差 / 千瓦</span><strong>${num(m.bias,2)}</strong></div></div><div style="margin-top:16px">${lineChart({labels:uploaded.filter((_,i)=>i%Math.max(1,Math.ceil(uploaded.length/200))===0).map(x=>x.timestamp.slice(5,16)),series:[{name:'实际',values:uploaded.filter((_,i)=>i%Math.max(1,Math.ceil(uploaded.length/200))===0).map(x=>x.actual),color:C.gray},{name:'预测',values:uploaded.filter((_,i)=>i%Math.max(1,Math.ceil(uploaded.length/200))===0).map(x=>x.pred),color:C.red}],unit:'千瓦',height:180})}</div><p class="muted" style="font-size:11px">${m.bias<0?'存在整体低估':'存在整体高估'}；${cfg.capacity>0?`nRMSE=${num(m.nrmse)}%，归一化容量${num(cfg.capacity)}千瓦峰值。`:'容量为0，不报告归一化误差。'}曲线最多抽样200点，统计使用全部记录。</p><button class="btn small" data-action="export-upload" style="margin-top:12px">下载评价结果</button>`;}
function renderPage(){const map={overview,forecast,dispatch:dispatchPage,remote,operations,benefits,lab,research:researchPage,energy:energyPage};$('#main-content').innerHTML=(map[page]||overview)()+footer();if(page==='benefits')enhanceBenefitHelp($('#main-content'));}
function go(p){page=navs.some(n=>n[0]===p)?p:'overview';location.hash=page;shell();window.scrollTo({top:0,behavior:'instant'});}
function openDetail(id){const title=modelList.find(x=>x[0]===id)?.[1]||'模型详情';$('#details').innerHTML=`<header class="dialog-head"><div><div class="eyebrow">MODEL DETAILS / 可追溯技术说明</div><h2 id="dialog-title">${title}</h2></div><button class="btn" data-close aria-label="关闭模型详情">关闭 ×</button></header><div class="dialog-body">${modelContent(id,b)}</div>`;$('#details').showModal();}
function openHelp(id){const h=benefitHelp[id];if(!h)return;$('#details').innerHTML=`<header class="dialog-head"><div><div class="eyebrow">FIELD GUIDE / 字段与结果说明</div><h2 id="dialog-title">${esc(h.title)}</h2></div><button type="button" class="btn" data-close aria-label="关闭说明">关闭 ×</button></header><div class="dialog-body benefit-help-body">${helpContent(id)}</div>`;$('#details').showModal();}
function interfaces(){ $('#details').innerHTML=`<header class="dialog-head"><h2 id="dialog-title">现场接入与设备接口规范</h2><button class="btn" data-close>关闭 ×</button></header><div class="dialog-body">${note('当前为静态前端，未启用真实设备HTTP/MQTT接口。下列是后续服务端的接口契约。','blue')}<h3>采集与预测</h3><p>建议由工业网关通过MQTT/HTTPS上传，时间使用ISO 8601并明确时区，功率千瓦，电量千瓦时。预报保留issued_at与valid_at，用于因果回放。</p><pre>POST /api/v1/telemetry\n{ "device_id":"PV-01", "timestamp":"2026-11-17T10:00:00+08:00",\n  "power_kw":120.5, "soc_pct":55, "wind_ms":4.2 }\n\nPOST /api/v1/forecast\n{ "model_id":"chronos2-adapter", "horizon_steps":96,\n  "quantiles":[0.05,0.5,0.95], "issued_at":"..." }</pre><h3>设备任务</h3><p>任务采用唯一ID、幂等键、审批状态和设备回执；服务端检查权限、生产约束、现场许可、联锁与急停。前端演练不直接复用为实控。</p><pre>POST /api/v1/missions\n{ "task_id":"...", "device_id":"UAV-01", "mode":"inspection",\n  "regions":["A04","A07"], "approval_id":"...", "dry_run":true }\n\nGET /api/v1/missions/{task_id}\n{ "status":"running", "progress_pct":25, "battery_pct":74 }</pre><p>详细字段与错误码见仓库 <a href="./docs/device-interface.md" target="_blank">device-interface.md</a>。现场控制端需独立鉴权，不能把设备密钥放入公开仓库或浏览器。</p></div>`;$('#details').showModal();}
function download(name,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500);}
function missionPackage(){return {platform:'光伏发电效率实时预测与智能调配系统',mode:'local_simulation_no_hardware',generated_at:new Date().toISOString(),environment:cfg,parameters:opcfg,device_battery_levels:levels,regions:[...selected].map(i=>`A${String(i+1).padStart(2,'0')}`),plan:currentPlan(),tasks,logs};}
function report(){const x=compute(),r=b.test.filter(x=>x.day),m=metrics(r.map(x=>x.actual),r.map(x=>x.pred)),mp=metrics(r.map(x=>x.actual),r.map(x=>x.persist));return {platform:'光伏发电效率实时预测与智能调配系统',generated_at:new Date().toISOString(),evidence:{source:'公开实测功率，非百口泉现场数据',forecast:m,relative_rmse_improvement_pct:(1-m.rmse/mp.rmse)*100,dispatch_replay:replay.stats,limits:'预测测试6日期含末日不完整；调配5完整日。前沿模型尚未验证。'},scenario:{type:'synthetic',environment:cfg,rolling:x.rolling.balance,same_asset_rule:x.rule.balance,no_storage:x.none.balance},operations:missionPackage(),finance:financial};}
async function doAction(a){if(a==='menu'){$('.app').classList.toggle('menu-open');return;}if(a==='interfaces'){interfaces();return;}if(a==='recompute'){for(const r of b.test){let p=clamp(predictMLP(r.input,weights),0,1)*b.capacity,h=Number(r.time.slice(11,13));r.pred=h>=21||h<4?0:p;}renderPage();toast('已使用导出权重完成560条测试样本的本地推理');return;}if(a==='select-high'){selected=new Set(Array.from({length:48},(_,i)=>i).filter(i=>loss(i)>10));renderPage();toast(`已选择${selected.size}个高损失分区`);return;}if(a==='select-all'){selected=new Set(Array.from({length:48},(_,i)=>i));renderPage();return;}if(a==='clear-selection'){selected.clear();renderPage();return;}if(a==='to-operations'){go('operations');return;}if(a==='auto-mission'){if(cfg.wind>8||cfg.rain>0){toast('当前天气不适合无人机；建议等待低风速、无降雨窗口');}else toast('已生成标准覆盖方案，请核对所选区域后部署演练');opcfg={altitude:cfg.cloud>.5?50:60,speed:cfg.dust>10?3:4,overlap:cfg.dust>10?80:75,robotSpeed:cfg.dust>10?4:6};save();renderPage();return;}if(a==='dispatch-recommend'){openRecommendation();return;}
 if(a==='export-report')download('光伏系统_分析报告.json',JSON.stringify(report(),null,2),'application/json');
 if(a==='export-mission')download('无人机机器人_作业方案.json',JSON.stringify(missionPackage(),null,2),'application/json');
 if(a==='export-dispatch'){const rows=compute().rolling.rows;download('日电能调配.csv','\uFEFF时间,光伏_千瓦,负荷_千瓦,购电_千瓦,外送_千瓦,充电_千瓦,放电_千瓦,弃光_千瓦,储能_千瓦时\n'+rows.map(r=>[r.label,r.pv,r.load,r.import,r.export,r.charge,r.discharge,r.curtail,r.energy].map(x=>typeof x==='number'?x.toFixed(5):x).join(',')).join('\n'),'text/csv;charset=utf-8');}
 if(a==='export-forecast')download('光伏预测结果.csv','\uFEFFtimestamp,actual_kw,pred_kw,persist_kw,ridge_kw,daytime\n'+b.test.filter(r=>forecastDay==='all'||r.time.startsWith(forecastDay)).map(r=>[r.time,r.actual,r.pred,r.persist,r.ridge,r.day].join(',')).join('\n'),'text/csv;charset=utf-8');
 if(a==='export-upload'&&uploaded)download('上传数据_评价结果.json',JSON.stringify({rows:uploaded.length,capacity:cfg.capacity,metrics:metrics(uploaded.map(x=>x.actual),uploaded.map(x=>x.pred),cfg.capacity)},null,2),'application/json');
}
function openRecommendation(){const x=compute();$('#details').innerHTML=`<header class="dialog-head"><h2 id="dialog-title">当前环境的建议方案</h2><button class="btn" data-close>关闭 ×</button></header><div class="dialog-body">${dispatchAdvice(x)}<h3>建议操作顺序</h3><p>1. 先核对负荷、电价与储能边界；2. 用独立天气预报更新出力分布；3. 比较规则与滚动成本，选择当期表现更好的策略；4. 对污染区复核后按净收益安排清扫；5. 以清扫后归一化出力检验恢复效果。</p>${note('自定义方案仅改变情景输入。正式投运前必须在本地数据上完成影子运行与限定区域验证。','blue')}</div>`;$('#details').showModal();}
function createTask(type){const p=currentPlan()[type];if(!p.allowed){toast(p.reasons.join('；'));return;}const t={id:`${type==='drone'?'UAV':'BOT'}-${Date.now().toString(36).toUpperCase()}`,type,status:'planned',progress:0,regions:[...selected],minutes:p.minutes,battery:p.battery,params:{...opcfg},created:new Date().toLocaleString('zh-CN')};tasks.push(t);log(`${t.id} 创建${type==='drone'?'巡检':'清扫'}演练，${selected.size}个分区`);save();renderPage();toast('已创建本地任务，点击开始演练推进流程');}
function handleTask(id,event){const idx=tasks.findIndex(t=>t.id===id);if(idx<0)return;let t=tasks[idx];if(['start','resume','step'].includes(event)){const env=taskGate(t,tasks,cfg,levels[t.type]);if(!env.allowed){if(t.status==='running'){t=transitionTask(t,'pause');tasks[idx]=t;log(`${id} 联锁暂停`);renderPage();}toast(env.reasons.join('；'));return;}}
 if(event==='step'){if(t.status!=='running')return;t={...t,progress:Math.min(100,t.progress+25)};if(t.progress===100){t=transitionTask(t,'complete');levels[t.type]=Math.max(0,levels[t.type]-t.battery);if(t.type==='robot'){cleared=[...new Set([...cleared,...t.regions])];}log(`${id} 完成演练；${t.type==='robot'?'已更新清扫分区标记，恢复效果待现场复测':'巡检影像待接入与现场复核'}`);}else log(`${id} 演练进度${t.progress}%`);}else {t=transitionTask(t,event);log(`${id} ${statusMap[t.status]}`);}tasks[idx]=t;save();renderPage();}
document.addEventListener('click',e=>{const bt=e.target.closest('button,[data-page]');if(!bt)return;try{if(bt.dataset.researchDetail){researchDetail(bt.dataset.researchDetail);return;}if(bt.dataset.researchTab){researchTab(bt.dataset.researchTab);return;}if(bt.dataset.researchAction){researchAction(bt.dataset.researchAction);return;}if(bt.hasAttribute('data-close')){$('#details').close();return;}if(bt.dataset.help){e.preventDefault();openHelp(bt.dataset.help);return;}if(bt.dataset.detail){openDetail(bt.dataset.detail);return;}if(bt.dataset.page){go(bt.dataset.page);return;}if(bt.dataset.cell!==undefined){remoteChoice=Number(bt.dataset.cell);selected.has(remoteChoice)?selected.delete(remoteChoice):selected.add(remoteChoice);renderPage();return;}if(bt.dataset.preset){cfg={...presets[bt.dataset.preset]};cache=null;save();renderPage();toast('环境预设已载入，可继续修改并计算');return;}if(bt.dataset.taskCreate){createTask(bt.dataset.taskCreate);return;}if(bt.dataset.task){handleTask(bt.dataset.task,bt.dataset.event);return;}if(bt.dataset.action)doAction(bt.dataset.action).catch(e=>toast(e.message));}catch(e){toast(e.message);}});
document.addEventListener('change',async e=>{try{if(await researchChange(e.target))return;if(e.target.id==='forecast-day'){forecastDay=e.target.value;renderPage();}if(e.target.id==='forecast-model'){forecastModel=e.target.value;renderPage();}if(e.target.id==='confidence'){confidence=Number(e.target.value);renderPage();}if(e.target.id==='csv-upload'){const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024)throw Error('文件超过5MB，请拆分数据');let data=parseCSV(await f.text());if(data.length>20000)throw Error('超过20,000行，请拆分数据');uploaded=data;renderPage();toast(`已校验${data.length}条记录并完成评价`);}}catch(err){toast(err.message);}});
document.addEventListener('submit',e=>{e.preventDefault();try{if(researchSubmit(e.target))return;const values=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,Number(v)]));if(e.target.id==='scenario-form'){if(values.deviceBattery!==cfg.deviceBattery)levels={drone:values.deviceBattery,robot:values.deviceBattery};cfg=validate({...cfg,...values});cache=null;save();renderPage();toast('已重算三种方案、能量平衡及建议');}if(e.target.id==='operation-form'){opcfg=values;save();renderPage();toast('已更新航线作业时间、电量与部署联锁');}if(e.target.id==='finance-form'){for(const k of Object.keys(financial))financial[k]=values[k];cfg=validate({...cfg,cleanCost:values.cleanCost,energyValue:values.energyValue});save();renderPage();toast('现金流与敏感性已更新');}}catch(err){toast(err.message);}});
document.addEventListener('pointermove',e=>{const target=e.target.closest('[data-tip]'),tip=$('#chart-tip');if(!target){tip.style.display='none';return;}tip.textContent=target.dataset.tip;tip.style.display='block';tip.style.left=Math.min(e.clientX+14,window.innerWidth-250)+'px';tip.style.top=Math.min(e.clientY+14,window.innerHeight-140)+'px';});
document.addEventListener('pointerleave',()=>{$('#chart-tip').style.display='none';});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(page!==p){page=navs.some(n=>n[0]===p)?p:'overview';shell();}});
$('#details').addEventListener('click',e=>{if(e.target===$('#details')){const r=$('#details').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#details').close();}});
configureResearch({render:renderPage,currentPage:()=>page,toast,download,dialog:(title,html)=>{$('#details').innerHTML=`<header class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="btn" data-close aria-label="关闭模型详情">关闭 ×</button></header><div class="dialog-body">${html}</div>`;$('#details').showModal();}});
try{[b,weights,replay]=await Promise.all(['benchmark.json','model.json','replay-dispatch.json'].map(async f=>{const r=await fetch(`./data/${f}`);if(!r.ok)throw Error(`数据载入失败：${f}`);return r.json();}));shell();}catch(e){$('#app').innerHTML=`<main style="padding:40px"><h1>工作空间暂未载入</h1><p>${esc(e.message)}</p><p>请通过HTTP服务或GitHub Pages打开。</p><button onclick="location.reload()">重新加载</button></main>`;}
